package dev.voxira.client.gui.menu;

import dev.voxira.client.VoxiraClient;
import net.minecraft.client.gui.GuiGraphicsExtractor;
import net.minecraft.client.renderer.RenderPipelines;
import net.minecraft.resources.Identifier;

/**
 * Textures and drawing helpers for the title screen.
 * The images are generated by {@code tools/generate_menu_assets.py}.
 */
public final class MenuArt {
    public static final Identifier SKY = tex("sky");
    public static final Identifier ECLIPSE = tex("eclipse");
    public static final Identifier MOUNTAINS = tex("mountains");
    public static final Identifier HILLS = tex("hills");
    public static final Identifier EMBLEM = tex("emblem");
    public static final Identifier EMBLEM_GLOW = tex("emblem_glow");
    public static final Identifier PILL = tex("pill");
    public static final Identifier PILL_OUTLINE = tex("pill_outline");
    public static final Identifier GLOW = tex("glow");
    public static final Identifier ICON_OPTIONS = tex("icon_options");
    public static final Identifier ICON_MODS = tex("icon_mods");
    public static final Identifier ICON_WEB = tex("icon_web");
    public static final Identifier ICON_QUIT = tex("icon_quit");

    /** Size of the artwork canvas the layers were designed for. */
    public static final float CANVAS_W = 1920f;
    public static final float CANVAS_H = 1080f;

    private MenuArt() {
    }

    private static Identifier tex(String name) {
        return VoxiraClient.id("textures/gui/menu/" + name + ".png");
    }

    /** Draws a whole texture scaled into the given box. */
    public static void image(GuiGraphicsExtractor ctx, Identifier id, int texW, int texH,
                             int x, int y, int w, int h, int argb) {
        if (w <= 0 || h <= 0 || (argb >>> 24) == 0) {
            return;
        }
        ctx.blit(RenderPipelines.GUI_TEXTURED, id, x, y, 0f, 0f, w, h, texW, texH, texW, texH, argb);
    }

    /** Draws a pill (fully rounded rectangle) from the 128x64 three-slice texture. */
    public static void pill(GuiGraphicsExtractor ctx, Identifier id, int x, int y, int w, int h, int argb) {
        if (w <= 0 || h <= 0 || (argb >>> 24) == 0) {
            return;
        }
        int cap = Math.min(h / 2, w / 2);
        ctx.blit(RenderPipelines.GUI_TEXTURED, id, x, y, 0f, 0f, cap, h, 32, 64, 128, 64, argb);
        int middle = w - cap * 2;
        if (middle > 0) {
            ctx.blit(RenderPipelines.GUI_TEXTURED, id, x + cap, y, 32f, 0f, middle, h, 64, 64, 128, 64, argb);
        }
        ctx.blit(RenderPipelines.GUI_TEXTURED, id, x + w - cap, y, 96f, 0f, cap, h, 32, 64, 128, 64, argb);
    }

    /** Multiplies the alpha of an ARGB color. */
    public static int alpha(int argb, float factor) {
        int a = Math.round(((argb >>> 24) & 0xFF) * Math.max(0f, Math.min(1f, factor)));
        return (a << 24) | (argb & 0xFFFFFF);
    }

    /** Linear blend between two ARGB colors. */
    public static int mix(int from, int to, float t) {
        t = Math.max(0f, Math.min(1f, t));
        int a = (int) (((from >>> 24) & 0xFF) + (((to >>> 24) & 0xFF) - ((from >>> 24) & 0xFF)) * t);
        int r = (int) (((from >> 16) & 0xFF) + (((to >> 16) & 0xFF) - ((from >> 16) & 0xFF)) * t);
        int g = (int) (((from >> 8) & 0xFF) + (((to >> 8) & 0xFF) - ((from >> 8) & 0xFF)) * t);
        int b = (int) ((from & 0xFF) + ((to & 0xFF) - (from & 0xFF)) * t);
        return (a << 24) | (r << 16) | (g << 8) | b;
    }

    /** Smooth 0..1 ease for intro animations. */
    public static float ease(float t) {
        t = Math.max(0f, Math.min(1f, t));
        return 1f - (1f - t) * (1f - t) * (1f - t);
    }
}
